    [QuizItem('g_wh_d1', 'Wh-Questions (प्रश्नवाचक शब्द)', 'A1', 'Asking about a place: ___ do you live?', ['Where', 'Who', 'Which'], 0, 'Where asks about a place.'), QuizItem('g_wh_d2', 'Wh-Questions (प्रश्नवाचक शब्द)', 'A1', '___ is your birthday? (asking for the date)', ['Why', 'When', 'Who'], 1, 'When asks about time.'), QuizItem('g_wh_d3', 'Wh-Questions (प्रश्नवाचक शब्द)', 'A1', '___ people are in the room?', ['How much', 'How many', 'How'], 1, 'People are countable.'), QuizItem('g_wh_d4', 'Wh-Questions (प्रश्नवाचक शब्द)', 'A1', 'Which question is correct?', ['Why you are sad?', 'Why are you sad?', 'Why you sad are?'], 1, 'Verb \'are\' comes before the subject.')]),
  GrammarLesson('g_past_simple', 'A2', 'Past Simple', 'Past Simple बीते हुए समय में पूरे हो चुके काम बताता है। Regular verb में -ed जुड़ता है (worked); irregular verb के अपने रूप होते हैं (go → went)। Negative और question में did + V1 आता है।', 'Use the past simple for actions that finished in the past.', 'Positive: Subject + V2.\nNegative: Subject + did not + V1.\nQuestion: Did + subject + V1?',
    [ExamplePair('I worked late yesterday.', 'मैंने कल देर तक काम किया।'), ExamplePair('She went to Delhi last week.', 'वह पिछले हफ़्ते दिल्ली गई।'), ExamplePair('We watched a movie last night.', 'हमने कल रात एक फ़िल्म देखी।'), ExamplePair('He didn\'t call me.', 'उसने मुझे फ़ोन नहीं किया।'), ExamplePair('Did you finish the report?', 'क्या आपने रिपोर्ट पूरी की?'), ExamplePair('They bought a new car in 2023.', 'उन्होंने 2023 में नई कार खरीदी।'), ExamplePair('I met the client on Monday.', 'मैं सोमवार को क्लाइंट से मिला।'), ExamplePair('The meeting started at ten.', 'मीटिंग दस बजे शुरू हुई।'), ExamplePair('She didn\'t see the message.', 'उसने संदेश नहीं देखा।'), ExamplePair('Where did you stay in Goa?', 'आप गोवा में कहाँ रुके थे?')],
