    [QuizItem('g_past_simple_d1', 'Past Simple', 'A2', 'Yesterday I ___ to the bank.', ['go', 'went', 'gone'], 1, 'Past of go is went.'), QuizItem('g_past_simple_d2', 'Past Simple', 'A2', 'She ___ the email last night. (negative)', ['didn\'t send', 'not sent', 'doesn\'t send'], 0, 'Did not + V1.'), QuizItem('g_past_simple_d3', 'Past Simple', 'A2', '___ you see the match?', ['Do', 'Did', 'Does'], 1, 'Past question uses did.'), QuizItem('g_past_simple_d4', 'Past Simple', 'A2', 'Past form of \'buy\':', ['buyed', 'bought', 'boughten'], 1, 'Buy is irregular: bought.')]),
  GrammarLesson('g_prepositions', 'A2', 'Prepositions: at, in, on', 'Time और जगह बताने के लिए at, in, on: at = सटीक समय या छोटी जगह (at 5 PM, at the station); on = दिन, तारीख़ या सतह (on Monday, on the table); in = महीना, साल, मौसम या बड़ी जगह (in May, in India)।', 'At, in and on show time and place.', 'at: exact time, small point (at 3 PM, at the bus stop).\non: days, dates, surfaces (on Monday, on 5 May, on the table).\nin: months, years, seasons, cities, countries (in May, in 2020, in Pune).',
    [ExamplePair('The meeting is at 3 PM.', 'मीटिंग दोपहर 3 बजे है।'), ExamplePair('I was born in 1998.', 'मेरा जन्म 1998 में हुआ।'), ExamplePair('See you on Monday.', 'सोमवार को मिलते हैं।'), ExamplePair('She lives in Mumbai.', 'वह मुंबई में रहती है।'), ExamplePair('The keys are on the table.', 'चाबियाँ मेज़ पर हैं।'), ExamplePair('He is waiting at the bus stop.', 'वह बस स्टॉप पर इंतज़ार कर रहा है।'), ExamplePair('We travel in summer.', 'हम गर्मियों में यात्रा करते हैं।'), ExamplePair('My birthday is on 5 May.', 'मेरा जन्मदिन 5 मई को है।'), ExamplePair('I study in the morning.', 'मैं सुबह पढ़ाई करता हूँ।'), ExamplePair('The class starts at noon.', 'क्लास दोपहर को शुरू होती है।')],
    [MistakePair('I will meet you in Monday.', 'I will meet you on Monday.', 'Days take on.'), MistakePair('The meeting is on 4 PM.', 'The meeting is at 4 PM.', 'Exact times take at.'), MistakePair('She was born at 1995.', 'She was born in 1995.', 'Years take in.')],
    [QuizItem('g_prepositions_d1', 'Prepositions: at, in, on', 'A2', 'The train leaves ___ 6:30.', ['in', 'on', 'at'], 2, 'Exact time: at.'), QuizItem('g_prepositions_d2', 'Prepositions: at, in, on', 'A2', 'I joined this company ___ 2021.', ['at', 'in', 'on'], 1, 'Years take in.'), QuizItem('g_prepositions_d3', 'Prepositions: at, in, on', 'A2', 'The party is ___ Saturday.', ['on', 'at', 'in'], 0, 'Days take on.'), QuizItem('g_prepositions_d4', 'Prepositions: at, in, on', 'A2', 'He lives ___ Kolkata.', ['at', 'on', 'in'], 2, 'Cities take in.')]),
  GrammarLesson('g_future', 'A2', 'Future: will and going to', 'Future के लिए will (अभी लिया फ़ैसला, वादा, अनुमान) और be going to (पहले से तय योजना या सबूत पर आधारित अनुमान) इस्तेमाल होते हैं।', 'Use will for sudden decisions, promises and predictions. Use be going to for plans and for predictions based on evidence.', 'will + V1 (I will call you).\nbe going to + V1 (I am going to start a course).\nNegative: will not (won\'t); am/is/are not going to.',
    [ExamplePair('I will call you later.', 'मैं आपको बाद में फ़ोन करूँगा।'), ExamplePair('It\'s cold. I\'ll close the window.', 'ठंड है। मैं खिड़की बंद कर देता हूँ।'), ExamplePair('I am going to learn English this year.', 'मैं इस साल अंग्रेज़ी सीखने वाला हूँ।'), ExamplePair('Look at the clouds. It is going to rain.', 'बादल देखिए। बारिश होने वाली है।'), ExamplePair('She will not join the meeting.', 'वह मीटिंग में शामिल नहीं होगी।'), ExamplePair('We are going to visit Jaipur next month.', 'हम अगले महीने जयपुर जाने वाले हैं।'), ExamplePair('Will you help me tomorrow?', 'क्या आप कल मेरी मदद करेंगे?'), ExamplePair('They won\'t arrive before noon.', 'वे दोपहर से पहले नहीं पहुँचेंगे।'), ExamplePair('I think she will pass the exam.', 'मुझे लगता है वह परीक्षा पास कर लेगी।'), ExamplePair('He is going to start a new job on Monday.', 'वह सोमवार को नई नौकरी शुरू करने वाला है।')],
    [MistakePair('I will to call you.', 'I will call you.', 'After will use the base verb without \'to\'.'), MistakePair('She will goes tomorrow.', 'She will go tomorrow.', 'After will use V1.'), MistakePair('I am going visit Goa.', 'I am going to visit Goa.', 'Be going to needs \'to\'.')],
    [QuizItem('g_future_d1', 'Future: will and going to', 'A2', 'The phone is ringing. I ___ answer it. (sudden decision)', ['am going to', 'will', 'would'], 1, 'Sudden decisions use will.'), QuizItem('g_future_d2', 'Future: will and going to', 'A2', 'She ___ start a course next week. (already planned)', ['will', 'is going to', 'goes'], 1, 'Plans use be going to.'), QuizItem('g_future_d3', 'Future: will and going to', 'A2', 'Which sentence is correct?', ['He will goes home.', 'He will go home.', 'He will to go home.'], 1, 'Will + base verb.'), QuizItem('g_future_d4', 'Future: will and going to', 'A2', 'Negative of \'They will come\':', ['They will not come.', 'They not will come.', 'They do not will come.'], 0, 'Will + not + V1.')]),
  GrammarLesson('g_present_perfect', 'B1', 'Present Perfect', 'Present Perfect (have/has + V3) उन कामों के लिए है जिनका संबंध अभी (वर्तमान) से है: अनुभव, अभी-अभी हुए काम, या अब तक चलता आ रहा समय (for/since)। बीते हुए निश्चित समय (yesterday, last week) के साथ इसे नहीं लगाते।', 'Use the present perfect for experiences, recent actions and situations that continue up to now.', 'Subject + have/has + V3.\nTime words: already, yet, ever, never, just, for, since.\nDo not use it with finished time words like yesterday or last week.',
    [ExamplePair('I have finished the report.', 'मैंने रिपोर्ट पूरी कर ली है।'), ExamplePair('She has worked here since 2020.', 'वह 2020 से यहाँ काम कर रही है।'), ExamplePair('Have you ever visited Goa?', 'क्या आप कभी गोवा गए हैं?'), ExamplePair('We have lived here for five years.', 'हम यहाँ पाँच साल से रह रहे हैं।'), ExamplePair('He hasn\'t replied yet.', 'उसने अभी तक जवाब नहीं दिया।'), ExamplePair('They have just arrived.', 'वे अभी-अभी पहुँचे हैं।'), ExamplePair('I have never eaten sushi.', 'मैंने कभी सुशी नहीं खाई।'), ExamplePair('Has the manager approved the plan?', 'क्या मैनेजर ने योजना मंज़ूर कर दी है?'), ExamplePair('She has already sent the email.', 'उसने ईमेल पहले ही भेज दिया है।'), ExamplePair('I have met him twice.', 'मैं उससे दो बार मिल चुका हूँ।')],
    [MistakePair('I have seen him yesterday.', 'I saw him yesterday.', 'A finished time (yesterday) needs the past simple.'), MistakePair('She has went home.', 'She has gone home.', 'Use V3 after has: gone.'), MistakePair('I am working here since 2020.', 'I have been working here since 2020.', '\'Since\' + a starting point needs a perfect tense.')],
    [QuizItem('g_present_perfect_d1', 'Present Perfect', 'B1', 'I ___ my homework. (it is done now)', ['have finished', 'finished yesterday', 'am finishing'], 0, 'Result that matters now: present perfect.'), QuizItem('g_present_perfect_d2', 'Present Perfect', 'B1', 'She has lived here ___ 2019.', ['for', 'since', 'from'], 1, 'Since + a starting point.'), QuizItem('g_present_perfect_d3', 'Present Perfect', 'B1', '___ you ever tried Japanese food?', ['Did', 'Have', 'Are'], 1, 'Ever + experience: have you ever...?'), QuizItem('g_present_perfect_d4', 'Present Perfect', 'B1', 'V3 of \'write\':', ['wrote', 'written', 'writed'], 1, 'Write – wrote – written.')]),
  GrammarLesson('g_modals', 'B1', 'Modal Verbs', 'Modal verbs (can, could, should, must, may) दूसरे verb के साथ आकर क्षमता, अनुमति, सलाह, ज़रूरत या संभावना बताते हैं। इनके बाद हमेशा base verb (V1) आता है, और इनमें -s नहीं लगता।', 'Modal verbs show ability, permission, advice, necessity and possibility. They are followed by the base verb.', 'can = ability / permission; could = polite request / past ability.\nshould = advice; must = strong necessity or rule.\nmay / might = possibility.\nModal + V1 (no to, no -s).',
    [ExamplePair('I can speak three languages.', 'मैं तीन भाषाएँ बोल सकता हूँ।'), ExamplePair('Could you send me the file, please?', 'क्या आप मुझे फ़ाइल भेज सकते हैं?'), ExamplePair('You should check the numbers again.', 'आपको आँकड़े फिर से जाँचने चाहिए।'), ExamplePair('Employees must wear ID cards.', 'कर्मचारियों को पहचान पत्र पहनना ज़रूरी है।'), ExamplePair('It may rain this evening.', 'आज शाम बारिश हो सकती है।'), ExamplePair('She might be in a meeting.', 'हो सकता है वह मीटिंग में हो।'), ExamplePair('You shouldn\'t ignore this problem.', 'आपको इस समस्या को अनदेखा नहीं करना चाहिए।'), ExamplePair('May I come in?', 'क्या मैं अंदर आ सकता हूँ?'), ExamplePair('We must finish this by Friday.', 'हमें यह शुक्रवार तक पूरा करना होगा।'), ExamplePair('He can\'t attend the call today.', 'वह आज की कॉल में शामिल नहीं हो सकता।')],
    [MistakePair('She can speaks English.', 'She can speak English.', 'After a modal use V1.'), MistakePair('You should to rest.', 'You should rest.', 'No \'to\' after should.'), MistakePair('He musts finish today.', 'He must finish today.', 'Modals do not take -s.')],
    [QuizItem('g_modals_d1', 'Modal Verbs', 'B1', '___ you help me, please? (polite)', ['Could', 'Must', 'Might'], 0, 'Could is a polite request.'), QuizItem('g_modals_d2', 'Modal Verbs', 'B1', 'You look tired. You ___ rest.', ['should', 'must to', 'can to'], 0, 'Should gives advice.'), QuizItem('g_modals_d3', 'Modal Verbs', 'B1', 'Which sentence is correct?', ['He cans swim.', 'He can swim.', 'He can swims.'], 1, 'Modal + base verb, no -s.'), QuizItem('g_modals_d4', 'Modal Verbs', 'B1', 'A strict rule: Passengers ___ show a ticket.', ['might', 'must', 'could'], 1, 'Must = strong necessity.')]),
  GrammarLesson('g_conditionals', 'B1', 'Conditionals: First and Second', 'Conditional sentences "अगर... तो" वाली बातें बताते हैं। First conditional: असली संभावना (If it rains, I will stay home)। Second conditional: काल्पनिक या कम संभावना वाली स्थिति (If I had more time, I would learn French)।', 'Conditional sentences talk about a condition and its result.', 'First: If + present simple, will + V1.\nSecond: If + past simple, would + V1.\nZero (facts): If + present simple, present simple.',
    [ExamplePair('If it rains, we will stay at home.', 'अगर बारिश हुई तो हम घर पर रहेंगे।'), ExamplePair('If you study hard, you will pass.', 'अगर तुम मेहनत से पढ़ोगे तो पास हो जाओगे।'), ExamplePair('If I have time, I\'ll call you.', 'अगर मेरे पास समय हुआ तो मैं फ़ोन करूँगा।'), ExamplePair('If I were rich, I would travel the world.', 'अगर मैं अमीर होता तो पूरी दुनिया घूमता।'), ExamplePair('If she had more time, she would learn French.', 'अगर उसके पास ज़्यादा समय होता तो वह फ़्रेंच सीखती।'), ExamplePair('If you heat ice, it melts.', 'अगर बर्फ़ को गरम करो तो वह पिघलती है।'), ExamplePair('We will start if everyone arrives on time.', 'अगर सब समय पर आए तो हम शुरू करेंगे।'), ExamplePair('If I were you, I would accept the offer.', 'अगर मैं आपकी जगह होता तो ऑफ़र स्वीकार कर लेता।'), ExamplePair('If the client agrees, we will sign today.', 'अगर क्लाइंट मान गया तो हम आज साइन करेंगे।'), ExamplePair('What would you do if you lost your job?', 'अगर आपकी नौकरी चली जाए तो आप क्या करेंगे?')],
    [MistakePair('If it will rain, we will stay.', 'If it rains, we will stay.', 'No will in the if-part.'), MistakePair('If I would have time, I would go.', 'If I had time, I would go.', 'Use the past simple after if in the second conditional.'), MistakePair('If I was you, I would go.', 'If I were you, I would go.', 'Standard English uses \'were\' after if in the second conditional.')],
    [QuizItem('g_conditionals_d1', 'Conditionals: First and Second', 'B1', 'If it ___ tomorrow, we will cancel the trip.', ['will rain', 'rains', 'rained'], 1, 'First conditional: if + present simple.'), QuizItem('g_conditionals_d2', 'Conditionals: First and Second', 'B1', 'If I ___ a bird, I would fly.', ['am', 'were', 'will be'], 1, 'Second conditional: if I were...'), QuizItem('g_conditionals_d3', 'Conditionals: First and Second', 'B1', 'If you ___ the button, the light turns on. (a fact)', ['press', 'will press', 'pressed'], 0, 'Zero conditional: present + present.'), QuizItem('g_conditionals_d4', 'Conditionals: First and Second', 'B1', 'If she ___ more money, she would buy a car.', ['has', 'had', 'will have'], 1, 'Second conditional: if + past simple.')]),
  GrammarLesson('g_passive', 'B2', 'Passive Voice', 'Passive Voice में काम करने वाले से ज़्यादा काम (या उसके असर) पर ध्यान होता है: The report was written by Riya. बनावट: be (is/are/was/were/will be...) + V3।', 'Use the passive voice when the action is more important than who does it.', 'Active: Subject + verb + object.\nPassive: Object + be + V3 (+ by agent).\nPresent: is/are + V3. Past: was/were + V3. Future: will be + V3.',
    [ExamplePair('The report was completed yesterday.', 'रिपोर्ट कल पूरी की गई।'), ExamplePair('English is spoken worldwide.', 'अंग्रेज़ी पूरी दुनिया में बोली जाती है।'), ExamplePair('The emails will be sent tomorrow.', 'ईमेल कल भेजे जाएँगे।'), ExamplePair('The new product was launched by our team.', 'नया उत्पाद हमारी टीम ने लॉन्च किया।'), ExamplePair('Mistakes are corrected quickly here.', 'यहाँ गलतियाँ जल्दी सुधारी जाती हैं।'), ExamplePair('The meeting has been postponed.', 'मीटिंग टाल दी गई है।'), ExamplePair('My phone was stolen.', 'मेरा फ़ोन चोरी हो गया।'), ExamplePair('Dinner is served at eight.', 'रात का खाना आठ बजे परोसा जाता है।'), ExamplePair('The contract must be signed today.', 'अनुबंध आज साइन होना ज़रूरी है।'), ExamplePair('Were you invited to the party?', 'क्या आपको पार्टी में बुलाया गया था?')],
    [MistakePair('The report written yesterday.', 'The report was written yesterday.', 'Passive needs a form of be + V3.'), MistakePair('The letter was send.', 'The letter was sent.', 'Use V3 (sent) after was.'), MistakePair('English speaks in many countries.', 'English is spoken in many countries.', 'English receives the action, so use the passive.')],
    [QuizItem('g_passive_d1', 'Passive Voice', 'B2', 'The room ___ every day. (clean)', ['cleans', 'is cleaned', 'cleaned'], 1, 'The room receives the action: is cleaned.'), QuizItem('g_passive_d2', 'Passive Voice', 'B2', 'The bridge ___ in 1990.', ['built', 'was built', 'is built'], 1, 'Past passive: was + V3.'), QuizItem('g_passive_d3', 'Passive Voice', 'B2', 'Passive of \'They will announce the result\':', ['The result will announced.', 'The result will be announced.', 'The result is announce.'], 1, 'Will be + V3.'), QuizItem('g_passive_d4', 'Passive Voice', 'B2', 'Which sentence is passive?', ['She wrote a mail.', 'A mail was written by her.', 'She is writing a mail.'], 1, 'Was + V3 = passive.')]),
];
